package kome.common.network;
import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import kome.common.KOMEReflection;import kome.common.data.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.util.ChatComponentText;
/** Server derives the relationship; client supplies only a departure action. */
public class KOMEPacketProgressionRelationshipAction implements IMessage { public static final int LEAVE_MASTER=0,LEAVE_LIEGE=1;public int action;public KOMEPacketProgressionRelationshipAction(){}public KOMEPacketProgressionRelationshipAction(int a){action=a;}public void fromBytes(ByteBuf b){action=b.readByte();}public void toBytes(ByteBuf b){b.writeByte(action);}public static class Handler implements IMessageHandler<KOMEPacketProgressionRelationshipAction,IMessage>{public IMessage onMessage(KOMEPacketProgressionRelationshipAction m,MessageContext c){EntityPlayerMP p=c.getServerHandler().playerEntity;KOMEWorldData d=KOMEWorldData.get(KOMEReflection.getWorld(p));KOMEPlayerProgression q=d.getProgression(KOMEReflection.getEntityUUID(p));KOMESerfKnightService.Result r=m.action==LEAVE_MASTER?KOMESerfKnightService.leaveSerfdomMaster(q.getSerfKnightProgression()):m.action==LEAVE_LIEGE?KOMESerfKnightService.leaveProspectiveLiege(q.getSerfKnightProgression()):null;if(r==null||!r.success){p.addChatMessage(new ChatComponentText(r==null?"Unknown relationship action.":r.reason));return null;}d.markDirty();KOMEProgressionAutoCompleter.syncPlayer(p,q);p.addChatMessage(new ChatComponentText(m.action==LEAVE_MASTER?"You are no longer serving your Serfdom Master.":"You are no longer pledged to your prospective liege."));return null;}}}
